import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Nakala 106｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Ulinganisho wa Kina: Kundi la Wawindaji dhidi ya Kundi la Usawa","description":"","frontmatter":{"title":"Nakala 106｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Ulinganisho wa Kina: Kundi la Wawindaji dhidi ya Kundi la Usawa","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","体系对比"],"related":["04-反掠夺主义核心论纲","01-锚点共生文明宣言","14-修炼境界统一划分"]},"headers":[],"relativePath":"sw/0106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"sw/0106_模块1-感元境-掠夺派vs共生派对比.md"}'),k={name:"sw/0106_模块1-感元境-掠夺派vs共生派对比.md"};function w(l,a,s,e,o,m){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="nakala-106-nguvu-ya-hisi-asili-ulinganisho-wa-kina-kundi-la-wawindaji-dhidi-ya-kundi-la-usawa" tabindex="-1">Nakala 106｜Nguvu ya Hisi Asili: Ulinganisho wa Kina Kundi la Wawindaji dhidi ya Kundi la Usawa <a class="header-anchor" href="#nakala-106-nguvu-ya-hisi-asili-ulinganisho-wa-kina-kundi-la-wawindaji-dhidi-ya-kundi-la-usawa" aria-label="Permalink to &quot;Nakala 106｜Nguvu ya Hisi Asili: Ulinganisho wa Kina Kundi la Wawindaji dhidi ya Kundi la Usawa&quot;">​</a></h1><ul><li>Moduli: Moduli ya Kwanza · Uboreshaji wa Kina wa Nguvu | Msingi wa Rejeo: Hati 04, 01, 14</li></ul><h2 id="utangulizi-hatua-ya-kuanzia-sawa-njia-mbili-zinazopingana" tabindex="-1">Utangulizi: Hatua ya Kuanzia Sawa, Njia Mbili Zinazopingana <a class="header-anchor" href="#utangulizi-hatua-ya-kuanzia-sawa-njia-mbili-zinazopingana" aria-label="Permalink to &quot;Utangulizi: Hatua ya Kuanzia Sawa, Njia Mbili Zinazopingana&quot;">​</a></h2><p>Nguvu ya Hisi Asili ni hatua ya kuanzia ya nguvu tisa, na pia njia ya kwanza ambapo Kabila Kumi na Elfu huchagua njia. Vipaji sawa, cosmos sawa, hata neno &quot;kuhisi nishati&quot; pia sawa, lakini Kundi la Wawindaji na Kundi la Usawa hutoa majibu yanayopingana kabisa. Makala hii inachukua Nguvu ya Hisi Asili kama kipande, inalinganisha kwa utaratibu tofauti za msingi za njia mbili katika njia, gharama na hatima, na kujibu swali kuu: kwa nini dari ya Kundi la Wawindaji daima ni chini ya sakafu ya Kundi la Usawa?</p><p>Kanuni Muhimu Sita za Juu ni kigawanyo cha njia mbili: Kanuni ya Kupinga Unyanyasaji — chanzo cha kigongo cha kwanza cha nishati huamua njia; Kanuni ya Jamhuri ya Kabila Kumi na Elfu — machoni mwa Kundi la Usawa Kabila Kumi na Elfu ni wanafunzi wenzao, machoni mwa Kundi la Wawindaji viumbe wote ni mawindo; Kanuni ya Kupanda Mwelekeo kwa Pamoja — Kundi la Usawa huwa na nguvu ili kupanda pamoja, Kundi la Wawindaji huwa na nguvu ili kufurahia pekee, kuzuia kipaji kikubwa kutumika kidogo; Kanuni ya Nidhamu ya Sababu-Natija — kila hatua ya Kundi la Usawa inaweza kurekodiwa, kufuatiliwa na kurekebishwa; Kanuni ya Kipaumbele cha Sheria — mfumo wa sheria wa ulinganisho Kundi la Wawindaji dhidi ya Kundi la Usawa ni thabiti na wenyewe, bila kubadilishwa kwa urahisi wa hadithi, unaweza kupanuka bila kikomo bila kuporomoka. Kanuni ya Usawa wa Ukombozi wa Kila Kiumbe inasisitiza kila mtu ana Nguvu Isiyo na Mwisho ya Msingi; wanafunzi wavivu wanabaki na nguvu ya msingi ya uhakika na hawataondolewa na wakati, wakati wenye tamaa na Vijana Wakuu wanaweza kuongeza ngazi za juu za nguvu ya bila kikomo; asili ya nguvu ya bila kikomo ni ya kila mtu, na unyanyasaji kawaida hupoteza maana.</p><h2 id="i-jedwali-la-ulinganisho-wa-mfumo" tabindex="-1">I. Jedwali la Ulinganisho wa Mfumo <a class="header-anchor" href="#i-jedwali-la-ulinganisho-wa-mfumo" aria-label="Permalink to &quot;I. Jedwali la Ulinganisho wa Mfumo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pande</th><th>Kundi la Wawindaji · Nguvu ya Hisi Asili</th><th>Kundi la Usawa · Nguvu ya Hisi Asili</th></tr></thead><tbody><tr><td>Chanzo cha nishati</td><td>Kumeza nishati ya mtu, kuibia fursa za hisi ya mtu</td><td>Kuchukua nishati ya bure ya cosmic kwa njia za kawaida, mzunguko wa pande mbili wa asili ya Kabila Kumi na Elfu</td></tr><tr><td>Njia ya hisi</td><td>Kuiba matokeo ya hisi ya mtu, haraka lakini mbaya</td><td>Kujaribu uamsho wa hisi ya mtu, msingi safi</td></tr><tr><td>Gharama ya kuvunja</td><td>Kutumia kipaji, asili isiyo safi, hatari zinaongezeka katika njia</td><td>Gharama ya kweli + ufuatiliaji wa nanga, inaweza kurekebishwa na kuanza tena</td></tr><tr><td>Mazingira ya usimamizi</td><td>Sheria ya msitu, bila usimamizi, bila wajibu</td><td>Mtandao wa Ālaya + usimamizi wa tabaka nyingi ulinzi wa mfululizo wote</td></tr><tr><td>Nafasi ya kijamii</td><td>Mawindo au mwindaji, moja kati ya mbili</td><td>Mjenzi mwenza, Njia kwa Kila Mtu</td></tr><tr><td>Hatima</td><td>Dari ya ufanisi: hatua moja zaidi haiwezi kutembea, haifikii Nguvu ya Asili</td><td>Nguvu ya Asili na zaidi, uzito wa ustaarabu hukua pamoja na mchango</td></tr></tbody></table><h2 id="ii-makosa-matatu-ya-kundi-la-wawindaji-yaliyopigwa-katika-nguvu-ya-hisi-asili" tabindex="-1">II. Makosa Matatu ya Kundi la Wawindaji Yaliyopigwa katika Nguvu ya Hisi Asili <a class="header-anchor" href="#ii-makosa-matatu-ya-kundi-la-wawindaji-yaliyopigwa-katika-nguvu-ya-hisi-asili" aria-label="Permalink to &quot;II. Makosa Matatu ya Kundi la Wawindaji Yaliyopigwa katika Nguvu ya Hisi Asili&quot;">​</a></h2><p>Makosa matatu ya unyanyasaji yaliyowasilishwa katika Hati 04 (Insha za Msingi za Kupinga Unyanyasaji) tayari yamepigwa kabisa katika Nguvu ya Hisi Asili:</p><ol><li>Kosa la cosmic: kuchukua cosmos kama uwanja mdogo wa uwindaji — tayari kujifunza &quot;kuiba&quot; katika Nguvu ya Hisi Asili, tangu siku ya kwanza kukubali mageuzi ni mchezo wa jumla ya sifuri</li><li>Kosa la maadili: kuweka haki ya mageuzi ya mwenye nguvu juu ya haki ya kuishi ya mnyonge — mara &quot;kumeza&quot; ikifunguliwa katika Nguvu ya Hisi Asili, hakuna kurudi</li><li>Kosa la ufanisi: kuamini unyanyasaji ni haraka zaidi — hisi iliyoibwa katika Nguvu ya Hisi Asili ina alama za nia ya mmiliki wa awali; gharama ya kusafisha baadaye ni kubwa zaidi ya mafunzo ya mtu</li></ol><p>Mwanafunzi wa Kundi la Wawindaji katika Nguvu ya Hisi Asili, kwa kasi ya haraka zaidi hutumia msingi wa gharama kubwa zaidi; mwanafunzi wa Kundi la Usawa katika Nguvu ya Hisi Asili, kwa hatua thabiti zaidi hujenga mtaji mzito zaidi.</p><h2 id="iii-mwindaji-mwenye-ustaarabu-wema-hauokoi-njia-ya-wawindaji" tabindex="-1">III. Mwindaji Mwenye Ustaarabu: Wema Hauokoi Njia ya Wawindaji <a class="header-anchor" href="#iii-mwindaji-mwenye-ustaarabu-wema-hauokoi-njia-ya-wawindaji" aria-label="Permalink to &quot;III. Mwindaji Mwenye Ustaarabu: Wema Hauokoi Njia ya Wawindaji&quot;">​</a></h2><p>Lazima kukabili kitu ngumu: &quot;mwindaji mwenye ustaarabu&quot; — ambaye ni mwema kiasi, hata kwa bidii anawalinda viumbe wote. Sifa zake: haanzishi uovu, yuko tayari kutoa kivuli, ni mwema kwa watu wake, lakini mfumo wote bado umewekwa juu ya msingi wa unyanyasaji — kumiliki njia kuu ya juu, kufurahia pekee ruhusa ya asili, kwa jina la &quot;kulinda&quot; kufanya &quot;kutoa&quot;.</p><p>Katika Nguvu ya Hisi Asili, elimu ya aina ya &quot;mwindaji mwenye ustaarabu&quot; ni: kumlisha mwenye kipaji kwa rasilimali bora, lakini kamwe kumpa njia — kwa sababu &quot;njia&quot; yenyewe ni bidii inayomilikiwa pekee. Hii ndiyo sababu hata mwenye nguvu mwenye wema hafiki urefu wa ustaarabu wa cosmic: yeye anasimama juu ya mfumo wa wawindaji, na dari ya mfumo wa wawindaji ni dari yake mwenyewe.</p><h2 id="iv-kwa-nini-kundi-la-wawindaji-lina-uhakika-wa-kushindwa-kihistoria" tabindex="-1">IV. Kwa nini Kundi la Wawindaji Lina Uhakika wa Kushindwa Kihistoria <a class="header-anchor" href="#iv-kwa-nini-kundi-la-wawindaji-lina-uhakika-wa-kushindwa-kihistoria" aria-label="Permalink to &quot;IV. Kwa nini Kundi la Wawindaji Lina Uhakika wa Kushindwa Kihistoria&quot;">​</a></h2><p>Hatima ya kimuundo ya ustaarabu wa Kundi la Wawindaji ni: mwenye nguvu akipo, ustaarabu unarudi nyuma. Utendaji wote wa mfumo unategemea nia njema na nguvu ya mtu binafsi juu — yuko hai, tu mpangilio unaendelea; yeye anaondoka, uwanja wa uwindaji huanza tena. &quot;Kutegemea hatua moja&quot; hii si kasoro ya maadili, bali kimuundo: mfumo wa wawindaji haukuwahi kuandika mpangilio katika taasisi, ulitoa mpangilio kwa mwenye nguvu binafsi.</p><p>Hii ndiyo fomu ya awali ya &quot;ubinafsi wa mhusika mkuu&quot;: kuishi kwa ustaarabu kunategemea mtu mmoja. Jibu la Ustaarabu wa Usawa wa Nanga ni kuandika amani katika taasisi na Netz der Gesetze (nanga, mahakama, baraza, mkataba wa uzalishaji) — hata Mwenye Nguvu Mkuu wa Njia akianguka, mtandao wa usawa unaendelea kufanya kazi.</p><h2 id="v-mtu-mbaya-aliye-kwenye-haki-kizingiti-cha-kupanda-na-njia-mpya" tabindex="-1">V. Mtu Mbaya Aliye kwenye Haki: Kizingiti cha Kupanda na Njia Mpya <a class="header-anchor" href="#v-mtu-mbaya-aliye-kwenye-haki-kizingiti-cha-kupanda-na-njia-mpya" aria-label="Permalink to &quot;V. Mtu Mbaya Aliye kwenye Haki: Kizingiti cha Kupanda na Njia Mpya&quot;">​</a></h2><p>Ili kuruka kutoka Kundi la Wawindaji hadi Kundi la Usawa, lazima kupita kizingiti cha kupanda kinachoitwa &quot;mtu mbaya aliye kwenye haki&quot;: kuthubutu kuvunja haki ya zamani iliyosafiwa, kuthubutu kuangusha mantiki ya msingi ya mfumo wa zamani, kutoogopa shinikizo la makundi ya maslahi yaliyopo, na kuandika upya mkataba wa haki wa usawa.</p><p>Mhusika mkuu Lín Hào ndiye mwakilishi wa njia hii: alizaliwa na asili ya chini, kwenda njia ya roho ya wanyama huumiza mwili, yeye ni mwathirika wa sheria za zamani, si mnufaika — alilazimika kujenga upya sheria, akatoa Njia D · Mwinyi wa Roho wa Sheria Bandia wa Rén Zú, akabadilisha uwindaji na uvunaji wa mwinyi wa roho na sheria bandia, akabadilika kutoka mwathirika wa mfumo wa wawindaji hadi mjenzi mpya wa ustaarabu wa usawa. Nguvu ya Hisi Asili ni mlango wa mwanzo kabisa wa kizingiti hiki: mtu ambaye tangu hatua ya kuanzia alichagua njia ya usawa, tayari yuko karibu zaidi na ustaarabu wa cosmic kuliko &quot;mwindaji mwenye ustaarabu&quot; aliyekwama juu ya mfumo wa wawindaji.</p><h2 id="vi-pointi-tano-za-msingi" tabindex="-1">VI. Pointi Tano za Msingi <a class="header-anchor" href="#vi-pointi-tano-za-msingi" aria-label="Permalink to &quot;VI. Pointi Tano za Msingi&quot;">​</a></h2><ul><li>Kupinga uharibifu wa nishati: Kundi la Wawindaji linapoteza kipaji katika mapambano ya ndani yanayoharibu, Kundi la Usawa linatumia kipaji katika ujenzi wa taratibu</li><li>Kupinga unyanyasaji: tofauti ya msingi ya njia mbili iko kwenye kigongo cha kwanza cha nishati katika Nguvu ya Hisi Asili</li><li>Kulinganisha paa la Táng Luó: &quot;ustawi&quot; wa aina ya Táng Luó bado ni mfumo wa kutoa — viumbe wote hutegemea wenye nguvu, si ujenzi wa pamoja; Kundi la Usawa lina Njia kwa Kila Mtu, hakuna anayetegemea mtu</li><li>Kufunika kwa Kabila Kumi na Elfu: machoni mwa Kundi la Wawindaji viumbe wote ni mawindo na zana, machoni mwa Kundi la Usawa Kabila Kumi na Elfu ni wanafunzi wenzao — ufunguzi wa 99% hauna ubaguzi</li><li>Ufunguzi wa kina wa anga nyingi zaidi: Kundi la Wawindaji linamiliki kila kitu, Kundi la Usawa tangu Nguvu ya Hisi Asili imefungua nguvu zote</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Ulinganisho wa Kundi la Wawindaji na Kundi la Usawa katika Nguvu ya Hisi Asili unajumuisha mgongano kuu wa historia yote ya cosmic: unyanyasaji huleta wenye nguvu wa muda na kurudi nyuma ya milele, usawa huleta ustawi wa kudumu na upandaji wa pamoja. Mwanafunzi wa Kundi la Wawindaji katika Nguvu ya Hisi Asili anajitahidi sana kushinda hatua ya kuanzia, tu kujua hatua ya mwisho ina dari yake mwenyewe; mwanafunzi wa Kundi la Usawa katika Nguvu ya Hisi Asili anachukua hatua ya kwanza kwa uthabiti, na kugundua mwisho wa njia ni Nguvu ya Nanga ya anga nyingi zaidi. Chaguo limeamuliwa katika hatua ya kuanzia — hii si hatima, hii ni kanuni.</p><h2 id="husika" tabindex="-1">Husika <a class="header-anchor" href="#husika" aria-label="Permalink to &quot;Husika&quot;">​</a></h2><ul><li>Hati zinazohusiana: <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./01-锚点共生文明宣言.html">01-锚点共生文明宣言</a> · <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a></li><li>Tovuti rasmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const y=i(k,[["render",w]]);export{d as __pageData,y as default};
